func (v SanValue) Equal(o attr.Value) bool {
	other, ok := o.(SanValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Dns.Equal(other.Dns) {
		return false
	}

	if !v.Emails.Equal(other.Emails) {
		return false
	}

	if !v.Ips.Equal(other.Ips) {
		return false
	}

	if !v.Uris.Equal(other.Uris) {
		return false
	}

	return true
}

